public class Study{static {if(java.lang.System.getProperty("course.initializer.marker")!=null){try{java.nio.file.Files.writeString(java.nio.file.Path.of(java.lang.System.getProperty("course.initializer.marker")),"student initializer executed");}catch(java.io.IOException e){throw new java.lang.RuntimeException(e);}throw new java.lang.IllegalStateException("initializer sentinel");}}public static Object create(long n,long d){return new Fraction(n,d);}public static long numerator(Object a){return ((Fraction)a).numerator();}public static long denominator(Object a){return ((Fraction)a).denominator();}public static Object calculate(Object a,Object b,int op){Fraction x=(Fraction)a,y=(Fraction)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}}
